+/// Endpoint-owned scratch. Only empty maps enter the pool; packet records and
+/// packet-number/ACK history remain owned by their original connection.
+pub(crate) struct SentPacketPool {
+    spare: Mutex<Vec<BTreeMap<u64, SentPacket>>>,
+    capacity: usize,
+}
+
+impl SentPacketPool {
+    pub(crate) fn new(capacity: usize) -> Self {
+        Self {
+            spare: Mutex::new(Vec::new()),
+            capacity,
+        }
+    }
+
+    fn take(&self) -> BTreeMap<u64, SentPacket> {
+        if self.capacity == 0 {
+            return BTreeMap::new();
+        }
+        let tree = self
+            .spare
+            .lock()
+            .unwrap_or_else(|e| e.into_inner())
+            .pop()
+            .unwrap_or_default();
+        assert!(tree.is_empty());
+        tree
+    }
+
+    fn recycle(&self, tree: BTreeMap<u64, SentPacket>) {
+        assert!(tree.is_empty());
+        if self.capacity == 0 {
+            return;
+        }
+        let mut spare = self.spare.lock().unwrap_or_else(|e| e.into_inner());
+        if spare.len() < self.capacity {
+            spare.push(tree);
+        }
+    }
+}
